from fractions import Fraction
from math import ceil


def _number(value):
    return int(value) if value.denominator == 1 else float(value)


def solve_transport(demand_tonnes, elevator_capacity_tonnes, rocket_capacity_kg, rocket_cost, cost_per_tonne):
    demand = Fraction(str(demand_tonnes))
    elevator_capacity = Fraction(str(elevator_capacity_tonnes))
    rocket_capacity = Fraction(str(rocket_capacity_kg)) / Fraction(1000)
    fixed_cost = Fraction(str(rocket_cost))
    elevator_rate = Fraction(str(cost_per_tonne))

    if demand < 0 or elevator_capacity < 0 or rocket_capacity <= 0:
        raise ValueError('capacities and demand must be physically valid')
    if fixed_cost <= 0:
        raise ValueError('rocket_cost must be positive for a finite optimal set')
    if elevator_rate < 0:
        raise ValueError('cost_per_tonne must be nonnegative')

    shortfall = max(Fraction(0), demand - elevator_capacity)
    first_launches = ceil(shortfall / rocket_capacity)
    full_launches = ceil(demand / rocket_capacity)
    candidates = []

    for launches in range(first_launches, full_launches + 1):
        e_tonnes = max(Fraction(0), demand - launches * rocket_capacity)
        if e_tonnes <= elevator_capacity:
            cost = elevator_rate * e_tonnes + fixed_cost * launches
            candidates.append((cost, e_tonnes, launches))

    if not candidates:
        raise ValueError('no feasible plan')

    best_cost = min(cost for cost, _, _ in candidates)
    return [
        {'e_tonnes': _number(e_tonnes), 'launches': launches, 'cost': _number(cost)}
        for cost, e_tonnes, launches in candidates
        if cost == best_cost
    ]
